-- 미술·디자인 전문학교 7곳 (kind='art') — 2026-09-22 공식 출처(CDS·입학처) 확인분, 확인 불가 값은 null
insert into public.schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url, kind, lac_rank, overall_accept_rate, ed_applied, ed_admitted, ed_cds_year, portfolio_req, portfolio_req_en, portfolio_source_url, art_programs) values
(137, 'Pratt Institute', '프랫 인스티튜트', null, null, 1140, 1380, '평균 GPA 3.64, 입학생의 32%가 GPA 4.0이다 (2025-2026 CDS)', 78.2, null, true, '{}'::text[], 'CDS에서 학업 GPA·에세이·재능(Talent/ability)·지원자의 관심도를 ''매우 중요''로 표시한다. 포트폴리오는 잠재력을 보는 입학 관점과 성취 수준을 보는 장학 관점, 두 가지로 평가한다고 밝힌다.', 'https://www.pratt.edu/wp-content/uploads/2026/02/2025-2026-CDS.xlsx', 'test-optional', '브루클린에 캠퍼스를 둔 미술·디자인·건축 전문 사립 대학이다.', '뉴욕주 브루클린에 있다.', false, false, true, false, null, null, '11월 중순', '1월 중순', 'https://www.pratt.edu/undergraduate-admissions/apply/', '2026-09-22', array['gpa','essay','talent','interest']::text[], 'https://www.pratt.edu/wp-content/uploads/2026/02/2025-2026-CDS.xlsx', 'A private art, design, and architecture college with its campus in Brooklyn.', 'The CDS lists academic GPA, the essay, talent/ability, and level of applicant''s interest as Very Important. Pratt states it reviews portfolios through two lenses: an admissions lens focused on potential and a scholarship lens focused on demonstrated accomplishment.', 'Located in Brooklyn, New York.', 'Average GPA 3.64; 32% of enrolled first-years had a 4.0 GPA (2025-2026 CDS)', 620, 19224, '2024-2025', false, 'Presidential Merit-Based Scholarship', false, false, 'All admitted first-year applicants, including international students, are automatically considered for merit scholarships with no separate application; awards for high school applicants are based on GPA and portfolio.', 'https://www.pratt.edu/admissions/undergraduate-admissions/finance-your-education/financial-aid-options/scholarships/', 'art', null, 86.4, null, null, null, '대부분의 전공은 10~20점의 시각 포트폴리오를 내야 하고, 그중 3~5점은 실물을 직접 보고 그린 관찰 작업이어야 한다. 포트폴리오는 Common App 제출 후 48시간 안에 이메일로 오는 링크를 통해 올린다. 영화(Film)는 시각 포트폴리오나 3~5분 영상에 글쓰기 과제를 더하고, 사진(Photography)은 10~20장의 사진, 문예창작(Writing BFA)은 최대 10쪽의 창작 글을 낸다.', 'Most programs require a visual portfolio of 10 to 20 artworks, including 3 to 5 pieces drawn from direct observation. The portfolio is uploaded via a link emailed within 48 hours of Common App submission. Film applicants submit a visual portfolio or a 3-5 minute video plus a writing component; Photography applicants submit 10-20 photographs; Writing (BFA) applicants submit up to 10 pages of creative writing.', 'https://www.pratt.edu/resources/undergraduate-application-requirements-high-school-applicants/', array['arts','graphic_design','fashion_design','film','architecture','game_design','industrial_design','interior_design']::text[]),
(138, 'Parsons School of Design at The New School', '파슨스 디자인 스쿨 (뉴스쿨)', null, null, null, null, null, null, null, null, '{}'::text[], '입학처는 이수 과목의 수준과 과목별 성적, 뉴스쿨 에세이 답변을 꼼꼼히 본다고 밝힌다. BFA 지원자는 포트폴리오에 드러난 기술적·개념적 역량을 높이 평가한다고 명시한다. 면접은 진행하지 않는다.', 'https://www.newschool.edu/parsons/how-to-apply-undergraduate/', 'test-free', '뉴욕시 뉴스쿨 산하의 미술·디자인 단과대학이다.', '뉴욕주 뉴욕시(맨해튼)에 있다.', true, false, true, false, '11월 초', null, '11월 초', '1월 중순', 'https://www.newschool.edu/parsons/how-to-apply-undergraduate/', '2026-09-22', null, null, 'The art and design college of The New School in New York City.', 'Admissions states it values the strength of each student''s curriculum and performance in each course, and pays close attention to the New School essay response. For BFA candidates, it holds in high regard the technical and conceptual abilities shown in the portfolio. Interviews are not offered.', 'Located in New York City (Manhattan), New York.', null, null, null, null, false, 'Merit-based scholarship (automatic)', null, null, 'All admitted Parsons applicants, including international students, are automatically considered for merit scholarships based on the strength of the application and portfolio; no separate application is required. International students are typically eligible only for merit scholarships.', 'https://www.newschool.edu/financial-aid/new-school-scholarships/', 'art', null, null, null, null, null, '모든 BFA 지원자는 8~12장의 이미지·슬라이드로 된 시각 포트폴리오를 내야 하고, 작업 과정을 보여주는 슬라이드를 최대 5장까지 더할 수 있다. Common App 제출 후 받는 Admission Hub 링크로 올리며, 제출 후에는 수정할 수 없다. 좋아하는 작품 최소 2점에는 아이디어·영감·재료 등 과정 설명을 붙여야 한다. BBA(Strategic Design and Management)는 포트폴리오가 선택이다.', 'All BFA applicants must submit a visual portfolio of 8 to 12 images or slides, with up to five optional additional process slides. It is uploaded through the Admission Hub link sent after Common App submission and cannot be edited once submitted. Applicants must describe their process, ideas, inspiration, and materials for at least two favorite pieces. The portfolio is optional for the BBA in Strategic Design and Management.', 'https://www.newschool.edu/parsons/how-to-apply-undergraduate/', array['arts','graphic_design','fashion_design','industrial_design','interior_design']::text[]),
(139, 'Rhode Island School of Design', '로드아일랜드 디자인스쿨 (RISD)', null, null, null, null, null, null, null, null, '{}'::text[], 'RISD는 포트폴리오에서 탐구, 과정, 발견, 개념적 사고, 창의적 문제 해결, 기술을 중요하게 본다고 밝힌다. 기술 연습보다 관점이 있는 작업과 다양한 재료·매체 실험, 위험을 감수하는 시도를 중시하며, 직접 관찰에 기반한 드로잉을 포함할 것을 권장한다. 에세이에서는 틀에 얽매이지 않는 개성 있는 표현을 환영한다고 밝힌다.', 'https://www.risd.edu/admissions/first-year/apply-risd', 'test-optional', 'RISD는 1877년 프로비던스에 설립된 사립 비영리 미술·디자인 대학으로, 1학년은 공통 기초과정(EFS)을 이수한 뒤 2학년부터 19개 학부 전공 중 하나를 선택한다.', '로드아일랜드주 프로비던스에 있다.', true, false, false, false, '11월 초', null, null, '1월 중순', 'https://www.risd.edu/admissions/first-year/apply-risd', '2026-09-22', null, null, 'RISD is a private, nonprofit art and design college founded in Providence in 1877; all first-year students take the shared Experimental and Foundation Studies (EFS) program before choosing one of 19 undergraduate majors in sophomore year.', 'RISD states that it values exploration, process, discovery, conceptual thought, creative problem-solving and skill in the portfolio. It looks for work with a point of view rather than technical exercises, values experimentation across materials and mediums and risk-taking, and recommends including drawing from direct observation. For the essay, it welcomes applicants who take risks in their expression.', 'Located in Providence, Rhode Island.', null, null, null, null, false, null, false, null, 'RISD states that institutional funding is awarded based on financial need at the time of admission; international applicants are considered by completing the RISD institutional financial aid form in the applicant portal. RISD notes it should not be assumed that aid offers will meet full financial need.', 'https://www.risd.edu/admissions/first-year/financing-your-education', 'art', null, 23.0, null, null, null, '포트폴리오는 필수이며, 최근 작업 12~20점을 Common App 지원 시작 후 SlideRoom으로 제출한다(SlideRoom 수수료 10달러 별도). 현재 별도의 필수 드로잉 과제(과거의 ''RISD drawing'' 과제)는 요구하지 않으며, 대신 사진·영상이 아닌 직접 관찰에 기반한 드로잉·페인팅을 일부 포함할 것을 강력히 권장한다. 리서치·준비 과정 작업은 최대 3슬라이드까지 넣을 수 있고, AI를 사용한 작업은 과정과 도구를 설명해야 한다.', 'A portfolio is required: 12–20 examples of recent work, uploaded to SlideRoom after starting the Common App (separate $10 SlideRoom fee). RISD currently does not require a separate drawing assignment (the former ''RISD drawing'' prompt); instead it strongly recommends including some drawing and/or painting from direct observation rather than from photos or video. Up to three slides may show research or preparatory work, and any AI-assisted work must include a description of the process and tools used.', 'https://www.risd.edu/admissions/first-year/apply-risd', array['arts','graphic_design','fashion_design','film','architecture','industrial_design','interior_design']::text[]),
(140, 'California Institute of the Arts', '캘리포니아 예술대학 (CalArts)', null, null, null, null, null, null, null, null, '{}'::text[], 'CalArts는 각 프로그램 교수진이 포트폴리오 또는 오디션, 아티스트 스테이트먼트, 추천서를 검토해 예술적 합격 여부를 결정한다고 밝힌다. 이후 입학처가 학업 이수 내역과 영어 점수를 검토해 학업 준비도를 확인한다. 미술 전공은 일반적인 기술 연습보다 개인적 관심사와 예술가로서의 정체성이 드러나는 작업을 원한다고 밝힌다.', 'https://calarts.edu/admissions-aid/admissions/faqs', 'test-optional', 'CalArts는 미술, 비평연구, 무용, 영화/비디오, 음악, 연극의 6개 스쿨로 이루어진 시각·공연 예술 전문 대학으로, 지원할 때부터 특정 전공 프로그램을 선택해야 한다.', '캘리포니아주 발렌시아에 있다.', false, false, false, false, null, null, null, '1월 초', 'https://calarts.edu/admissions-aid/admissions/application-process/application-deadlines-and-fees', '2026-09-22', null, null, 'CalArts is a visual and performing arts institute made up of six schools—Art, Critical Studies, Dance, Film/Video, Music and Theater—and applicants must choose a specific program of study when they apply.', 'CalArts states that the faculty of each program decide artistic acceptance after considering the audition or portfolio, the artist statement and the letters of recommendation. The Office of Admissions then reviews academic coursework and any language test scores to confirm readiness. The BFA Art program asks for personal work that shows who applicants are as artists rather than generic technical exercises.', 'Located in Valencia, California.', null, null, null, null, null, 'CalArts merit-based institutional scholarships', null, null, 'International students are eligible for select institutional scholarships, typically based on artistic merit as judged from the portfolio, audition and/or writing sample; all applicants are automatically considered with no separate application. CalArts states these funds are limited and competitive and do not cover a student''s entire tuition.', 'https://calarts.edu/admissions-aid/admissions/international-applicants', 'art', null, 40.0, null, null, null, '모든 학부 지원자는 전공별 포트폴리오 또는 오디션(일부는 둘 다)과 아티스트 스테이트먼트, 짧은 자기소개 영상을 CalArts 자체 지원 시스템으로 제출하며, SlideRoom 등 외부 플랫폼은 받지 않는다. BFA Art는 최근 3년 작업 위주 약 20슬라이드(영상 합계 7분 이내)를, BFA Character Animation은 실제 대상을 보고 그린 관찰 드로잉 최소 15점과 스토리텔링 작업을 요구한다. 음악(예: Instrumental Arts)은 연주 영상 최소 3개와 대면 인터뷰·오디션이 필요하다.', 'Every undergraduate applicant submits a program-specific portfolio or audition (some programs require both), an artist statement and a short video introduction through the CalArts application; SlideRoom and other third-party platforms are not accepted. BFA Art asks for about 20 slides, preferably from the last three years (total video runtime up to 7 minutes), and BFA Character Animation requires at least 15 observational drawings from life plus storytelling work. Music programs such as Instrumental Arts require at least three performance videos and an in-person interview and audition.', 'https://calarts.edu/admissions-aid/admissions/admission-requirements', array['arts','graphic_design','film','music']::text[]),
(141, 'The Cooper Union for the Advancement of Science and Art', '쿠퍼 유니언', null, null, null, null, null, null, null, null, '{}'::text[], '미술대학 지원자는 포트폴리오·스케치북과 함께 학교가 출제하는 Hometest를 제출하며, 학교는 이를 통해 시각적 상상력, 콘셉트 전개, 손으로 만드는 능력, 지시를 따르고 시간을 관리하는 능력을 본다고 밝힌다. 건축대학은 Studio Test를 입학 심사의 핵심으로 두고 창의적 사고와 문제 해결 능력을 평가하며, 건축 경험은 요구하지 않는다. 학부 입학 과정에서 인터뷰는 진행하지 않는다.', 'https://cooper.edu/sites/default/files/uploads/assets/institutional-statistics.pdf', 'test-optional', '건축·미술·공학 3개 단과대학으로 이루어진 뉴욕의 소규모 사립대로, 모든 학부생에게 반액 등록금 장학금을 준다.', '뉴욕주 뉴욕시에 있다.', true, false, false, false, '12월 초', null, null, '1월 초', 'https://cooper.edu/admissions/applying-to-cu/art', '2026-09-22', null, null, 'A small private college in New York City made up of schools of architecture, art, and engineering, awarding every undergraduate a half-tuition scholarship.', 'School of Art applicants submit a portfolio and sketchbook along with the school-issued Hometest, which the school says shows visual imagination, concept development, hands-on making, and how well applicants follow directions and manage time. The School of Architecture treats its Studio Test as a cornerstone of admissions, assessing creative thinking and problem-solving, and requires no prior architecture experience. No interviews are conducted in undergraduate admissions.', 'Located in New York City, New York.', null, null, null, null, null, 'Half-Tuition Scholarship', null, false, 'Cooper Union awards every admitted undergraduate, domestic and international, a half-tuition scholarship, currently valued at $22,275 per year. It does not offer separate academic merit scholarships; additional aid is need-based, and international students are not eligible for federal or state aid.', 'https://cooper.edu/admissions/international/applicants', 'art', null, 16.4, null, null, null, '미술대학(BFA)은 최근 작품 15-20점의 포트폴리오와 스케치북, 그리고 학교가 출제하는 Hometest(시각 과제 6개·서술 과제 10개, 약 한 달 안에 완성)가 필수이며, Hometest는 디지털본과 실물본을 모두 내야 한다. 과제 안내는 지원 마감 후 일주일 안에 지원자 포털에 올라오고, 포트폴리오는 Hometest와 함께 제출한다(ED 1월 초, RD 2월 초). ED와 RD 지원자는 서로 다른 Hometest를 받는다. 건축대학(BArch)은 포트폴리오 대신 약 한 달짜리 Studio Test를 같은 일정으로 제출한다.', 'The School of Art (BFA) requires a portfolio of 15-20 recent works, a sketchbook, and the school-issued Hometest (6 visual and 10 written prompts, about one month to complete); both a digital and a physical version of the Hometest are required. Instructions appear in the applicant portal within a week of the application deadline, and the portfolio is submitted with the Hometest (early January for ED, early February for RD). ED and RD applicants receive different Hometests. The School of Architecture (BArch) instead requires a roughly month-long Studio Test on the same schedule.', 'https://cooper.edu/admissions/applying-to-cu/art', array['arts','architecture']::text[]),
(142, 'School of the Art Institute of Chicago', '시카고 예술대학(SAIC)', null, null, null, null, null, null, true, null, '{}'::text[], '학교는 지원서·포트폴리오·아티스트 스테이트먼트·추가 자료를 종합적으로 보고 신입생을 선발한다고 밝힌다. 포트폴리오에서는 기술보다 지원자의 관심사와 탐구·실험하려는 태도를 보여 주기를 원하며, 사진이나 다른 작가의 작품을 그대로 옮긴 작업은 권하지 않는다. 합격과 동시에 같은 자료로 장학금 심사도 이루어진다.', 'https://www.saic.edu/admissions/undergraduate/faq', 'test-optional', '시카고 미술관(Art Institute of Chicago)과 연계된 미술대학으로, 전공 구분 없는 BFA in Studio 안에서 여러 학과 수업을 자유롭게 듣는 구조다.', '일리노이주 시카고에 있다.', false, false, true, false, null, null, '11월 중순', '1월 중순', 'https://www.saic.edu/admissions/undergraduate/how-apply-freshman', '2026-09-22', null, null, 'An art school affiliated with the Art Institute of Chicago museum, where students in the BFA in Studio take courses freely across departments without a declared major.', 'The school says it selects its incoming class through a holistic view of the application, portfolio, artist''s statement, and supplemental materials. It wants the portfolio to show the applicant''s interests and willingness to explore and experiment rather than technical skill alone, and discourages work copied directly from photographs or other artists'' works. Merit scholarships are decided from the same materials at the time of admission.', 'Located in Chicago, Illinois.', null, null, null, null, null, 'SAIC Merit Scholarship', null, null, 'International undergraduates are reviewed for SAIC merit scholarships during the admissions process, based on the portfolio, artist''s statement and other materials, with no separate application. The Early Action/Priority Merit deadline gives the widest access to merit awards; international students are not eligible for U.S. federal aid.', 'https://www.saic.edu/admissions/undergraduate/info-international-students', 'art', null, 57.0, null, null, null, 'BFA 지원자는 최근 작품 10-15점의 포트폴리오를 SlideRoom으로 제출하며, 매체 제한이나 지정 과제는 없다. AI를 활용한 작품은 SlideRoom 설명란에 과정과 사용 도구를 밝혀야 한다. BFA in Writing은 글 10쪽 이내, BA 미술사는 5-7쪽 글쓰기 샘플과 작품 5-10점 등 학위별 요건이 다르다. 인터뷰나 오디션은 없으며, 제출한 포트폴리오가 그대로 장학금 심사에 쓰인다.', 'BFA applicants submit a portfolio of 10-15 recent works via SlideRoom, with no media limitations and no assigned projects. Any AI-assisted work must note the process and tools in the SlideRoom description. Requirements vary by degree: BFA in Writing asks for up to 10 pages of writing, and BA Art History asks for a 5-7 page writing sample plus 5-10 portfolio pieces. There is no interview or audition, and the admission portfolio is also used for merit scholarship review.', 'https://www.saic.edu/admissions/undergraduate/portfolio-requirements', array['arts','graphic_design','fashion_design','film','interior_design']::text[]),
(143, 'School of Visual Arts', '스쿨 오브 비주얼 아츠 (SVA)', null, null, null, null, null, null, null, null, '{}'::text[], 'SVA는 학업 이력이 입학 심사에서 중요한 역할을 한다고 밝히며, 미술 작업과 함께 인문학적 소양도 중시한다. 포트폴리오는 지원자의 창작·기술적 경험과 성취를 보여 주는 작품 모음으로 정의되며, 성장 과정보다 현재 실력을 대표하는 가장 강한 작품을 내라고 안내한다.', 'https://sva.edu/admissions/how-to-apply/undergraduate-application-requirements', 'test-optional', 'SVA는 뉴욕시에 있는 미술·디자인 전문 대학으로, 일러스트레이션·파인아트·디자인·애니메이션·영화 등 11개 BFA 전공을 운영한다.', '뉴욕주 뉴욕시(맨해튼)에 있다.', false, false, true, false, null, null, '12월 초', '2월 초', 'https://sva.edu/admissions/how-to-apply/undergraduate-application-requirements', '2026-09-22', null, null, 'SVA is an art and design college in New York City offering 11 BFA majors, including Illustration, Fine Arts, Design, Animation and Film.', 'SVA states that an applicant''s academic history plays an important role in admission and stresses aptitude in the humanities alongside creative work. It defines the portfolio as a collection representing the applicant''s creative and technical experiences and accomplishments, and asks applicants to submit their strongest work that represents their current skill set rather than showing growth.', 'Located in New York City (Manhattan), New York.', null, null, null, null, null, 'Silas H. Rhodes Scholarship', null, null, 'International students are eligible for the merit-based Silas H. Rhodes Scholarship (first-time freshmen, full-time, minimum 3.0 GPA); there is no separate application, and freshman materials must be submitted by February 1. The Gustave Blache III Art Scholarship (partial tuition, December 1 deadline) is also open to international first-time freshmen.', 'https://sva.edu/admissions/financial-resources/scholarships', 'art', null, null, null, null, null, '모든 BFA 전공에 포트폴리오가 필요하다. 일반 BFA 전공은 15~20점의 이미지를 내야 하며, 그중 최소 3점은 사진·화면이 아닌 실물을 직접 보고 그린 관찰 작품이어야 한다. BFA Film은 3~5분 분량의 필름 릴 또는 두 파트로 된 필름 에세이(500단어+1,000단어)를, BFA Photography and Video는 스틸 사진 5점 이상을 포함한 사진·영상 10~20점을 제출한다. 제출은 SlideRoom을 권장하며 YouTube·Vimeo 링크도 쓸 수 있다.', 'A portfolio is required for all BFA majors. Most BFA majors require 15-20 images, including at least 3 pieces created from direct observation (not from a photograph or screen). BFA Film requires a 3-5 minute film reel or a two-part film essay (500 + 1,000 words), and BFA Photography and Video requires 10-20 photographs or videos with at least 5 still photographs. SlideRoom submission is encouraged, and links via YouTube or Vimeo are accepted.', 'https://sva.edu/admissions/how-to-apply/undergraduate-application-requirements', array['arts','graphic_design','film','interior_design']::text[])
on conflict (id) do update set name=excluded.name, name_ko=excluded.name_ko, usnews_rank=excluded.usnews_rank, tier=excluded.tier, sat_mid50_low=excluded.sat_mid50_low, sat_mid50_high=excluded.sat_mid50_high, gpa_note=excluded.gpa_note, intl_accept_rate=excluded.intl_accept_rate, need_blind_intl=excluded.need_blind_intl, demonstrated_interest=excluded.demonstrated_interest, direct_admit_majors=excluded.direct_admit_majors, what_they_value=excluded.what_they_value, source_url=excluded.source_url, test_policy=excluded.test_policy, intro_ko=excluded.intro_ko, location_note=excluded.location_note, ed_offered=excluded.ed_offered, ed2_offered=excluded.ed2_offered, ea_offered=excluded.ea_offered, rea_offered=excluded.rea_offered, ed_timing=excluded.ed_timing, ed2_timing=excluded.ed2_timing, ea_timing=excluded.ea_timing, rd_timing=excluded.rd_timing, deadlines_source_url=excluded.deadlines_source_url, deadlines_verified_at=excluded.deadlines_verified_at, c7_very_important=excluded.c7_very_important, c7_source_url=excluded.c7_source_url, intro_en=excluded.intro_en, what_they_value_en=excluded.what_they_value_en, location_note_en=excluded.location_note_en, gpa_note_en=excluded.gpa_note_en, intl_aid_count=excluded.intl_aid_count, intl_aid_avg=excluded.intl_aid_avg, intl_aid_year=excluded.intl_aid_year, meets_full_need_intl=excluded.meets_full_need_intl, merit_intl=excluded.merit_intl, meets_full_need_all=excluded.meets_full_need_all, no_loan=excluded.no_loan, merit_note=excluded.merit_note, aid_source_url=excluded.aid_source_url, kind=excluded.kind, lac_rank=excluded.lac_rank, overall_accept_rate=excluded.overall_accept_rate, ed_applied=excluded.ed_applied, ed_admitted=excluded.ed_admitted, ed_cds_year=excluded.ed_cds_year, portfolio_req=excluded.portfolio_req, portfolio_req_en=excluded.portfolio_req_en, portfolio_source_url=excluded.portfolio_source_url, art_programs=excluded.art_programs;
update public.schools set avg_gpa=3.64, avg_gpa_scale='4.0 scale', avg_gpa_year='CDS 2025-26', avg_gpa_source_url='https://www.pratt.edu/wp-content/uploads/2026/02/2025-2026-CDS.xlsx' where id=137;

-- Cooper Union: 공과대학 정보 보강 (2026-09-22, cooper.edu 공식)
update public.schools set intro_ko='건축·미술·공학 3개 단과대학으로 이루어진 뉴욕의 소규모 사립대로, 모든 학부생에게 반액 등록금 장학금을 준다. 앨버트 너켄 공과대학은 화학·토목·전기·기계공학(B.E.)과 컴퓨터과학·일반공학(B.S.) 과정을 운영하며 학부생의 절반 이상이 공학 전공이다.', intro_en='A small private college in New York City made up of schools of architecture, art, and engineering, awarding every undergraduate a half-tuition scholarship. The Albert Nerken School of Engineering offers B.E. programs in chemical, civil, electrical and mechanical engineering plus B.S. programs in computer science and general engineering, and engineering students make up over half of the undergraduate body.', what_they_value='미술대학 지원자는 포트폴리오·스케치북과 함께 학교가 출제하는 Hometest를 제출하며, 학교는 이를 통해 시각적 상상력, 콘셉트 전개, 손으로 만드는 능력, 지시를 따르고 시간을 관리하는 능력을 본다고 밝힌다. 건축대학은 Studio Test를 입학 심사의 핵심으로 두고 창의적 사고와 문제 해결 능력을 평가하며, 건축 경험은 요구하지 않는다. 공과대학은 미술·건축과 달리 SAT/ACT 제출이 필수이고 포트폴리오·Hometest는 없으며, 고교에서 미적분·화학·물리를 각 1년 이상 이수할 것과 STEM 교사 추천서 1통 이상을 요구한다. 학부 입학 과정에서 인터뷰는 진행하지 않는다.', what_they_value_en='School of Art applicants submit a portfolio and sketchbook along with the school-issued Hometest, which the school says shows visual imagination, concept development, hands-on making, and how well applicants follow directions and manage time. The School of Architecture treats its Studio Test as a cornerstone of admissions, assessing creative thinking and problem-solving, and requires no prior architecture experience. The School of Engineering, unlike Art and Architecture, requires the SAT or ACT and has no portfolio or Hometest; it asks applicants to complete at least one year each of calculus, chemistry and physics in high school and to submit at least one recommendation from a STEM teacher. No interviews are conducted in undergraduate admissions.', merit_note='Cooper Union awards every enrolled undergraduate, domestic and international and in all three schools (art, architecture, engineering), a half-tuition scholarship, currently valued at $22,275 per year. It does not offer separate academic merit scholarships; additional aid is need-based, and international students are not eligible for federal or state aid.', direct_admit_majors=array['arts','architecture','engineering','cs']::text[] where id=141;

-- FIT (id 144) 추가 — 2026-09-22, CDS 2025-26·fitnyc.edu 공식
insert into public.schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url, kind, lac_rank, overall_accept_rate, ed_applied, ed_admitted, ed_cds_year, portfolio_req, portfolio_req_en, portfolio_source_url, art_programs) values (144, 'Fashion Institute of Technology', '패션 인스티튜트 오브 테크놀로지 (FIT, SUNY)', null, null, null, null, '평균 GPA 3.6 (신입생 98% 제출, 2025-2026 CDS)', 64.4, null, false, '{}'::text[], 'FIT는 공식적으로 학업 성취, 대학 수준에서의 성공을 예측하는 성취, 그리고 입증된 재능(demonstrated talent)을 심사 요소로 본다고 밝힌다. CDS C7에서는 교과 난이도, GPA, 에세이, 재능/능력을 ''매우 중요''로 표시하며, 시험 점수·추천서·면접·지원자의 관심도는 고려하지 않는다. 예술·디자인 및 영화 전공 지원자는 포트폴리오로 예술적·창의적 능력을 입증해야 하며, 에세이에서는 해당 전공을 선택한 이유와 준비 과정을 묻는다.', 'https://www.fitnyc.edu/documents/ire/cds-2025-26-updated3.pdf', 'test-free', '뉴욕주립대(SUNY) 소속 공립 예술·디자인·패션 비즈니스 대학으로, 고교 졸업생은 2년제 AAS 과정으로 입학한 뒤 2년제 학사(BFA/BS) 과정에 다시 지원하는 ''2+2'' 구조다.', '뉴욕주 뉴욕시(맨해튼)에 있다.', false, false, false, false, null, null, null, '1월 초', 'https://www.fitnyc.edu/admissions/undergraduate-applicants/apply/deadlines.php', '2026-09-22', array['rigor','gpa','essay','talent']::text[], 'https://www.fitnyc.edu/documents/ire/cds-2025-26-updated3.pdf', 'A public college of the State University of New York (SUNY) for art, design, and fashion business; students entering from high school begin a two-year AAS program and then apply to a two-year bachelor''s (BFA/BS) program in FIT''s ''2+2'' structure.', 'FIT officially states that academic accomplishments, achievements that predict success at the college level, and demonstrated talent are the factors the Admissions Committee considers. In CDS C7 it marks rigor of secondary record, GPA, application essay, and talent/ability as Very Important, and does not consider test scores, recommendations, interviews, or level of applicant''s interest. Applicants to School of Art and Design majors and to Film and Media must show artistic and creative ability through a portfolio, and the essay asks why the applicant chose that major and how they prepared for it.', 'Located in New York City (Manhattan), New York.', 'Average GPA 3.6 (98% of first-years submitted, 2025-2026 CDS)', null, null, null, false, null, false, false, 'FIT''s financial aid office states that international students are not eligible for financial assistance from FIT; they may only borrow through the Alternative (private) Loan Program, usually with a creditworthy U.S. co-signer. F-1 visa holders are not eligible for the New York State resident tuition rate and pay the out-of-state rate.', 'https://www.fitnyc.edu/admissions/costs/financial-aid/eligibility-and-policies/index.php', 'art', null, 67.0, null, null, null, 'School of Art and Design의 모든 전공과 Film and Media 전공은 포트폴리오가 필수이며, SUNY 지원서 접수 후 지원자 포털의 링크를 통해 SlideRoom으로 제출한다(수수료 $10, 가을학기 마감 2월 초). 요구 내용은 전공별로 다르다: Fashion Design AAS는 짧은 에세이 + 디자인 프로젝트 2개(스포츠웨어 코디 3-6장, 패션 드로잉 4-8장) + 직접 봉제한 의상 사진 4-9장(총 11-23점), Illustration AAS는 에세이 2편 + 실물 관찰 드로잉 7-10점 포함 14-20점, Fine Arts AAS는 에세이 1편 + 12-20점(관찰 드로잉 4점 이상), Communication Design AAS는 에세이 2편 + 10-15점, Interior Design AAS는 에세이 2편 + 13-19장(실물 모형 사진 3장 포함), Film and Media AAS는 이미지 8-10장·5분 이내 영상·6쪽 이내 글 중 택 1 + 에세이다. Fashion Business Management 등 Jay and Patty Baker School of Business and Technology 전공은 포트폴리오를 받지 않는다. 면접과 추천서는 없다.', 'A portfolio is required for every School of Art and Design major and for Film and Media; after the SUNY application is received, applicants submit it through SlideRoom via a link in the applicant portal ($10 fee; fall deadline early February). Requirements are major-specific: Fashion Design AAS asks for a short essay, two design projects (3-6 sportswear-coordinate images and 4-8 fashion drawings) and 4-9 photos of garments the applicant sewed (11-23 items total); Illustration AAS asks for two essays and 14-20 pieces including 7-10 drawings/paintings from direct observation; Fine Arts AAS one essay and 12-20 pieces with at least four observational drawings; Communication Design AAS two essays and 10-15 pieces; Interior Design AAS two essays and 13-19 images including three photos of a physical model; Film and Media AAS one of 8-10 images, a film up to 5 minutes, or up to 6 pages of writing, plus an essay. Majors in the Jay and Patty Baker School of Business and Technology, such as Fashion Business Management, do not accept a portfolio. There are no interviews and no recommendation letters.', 'https://www.fitnyc.edu/admissions/undergraduate-applicants/apply/portfolio/index.php', array['arts','graphic_design','fashion_design','interior_design','film','game_design']::text[]) on conflict (id) do nothing;
update public.schools set avg_gpa=3.6, avg_gpa_scale='4.0 scale', avg_gpa_year='CDS 2025-26', avg_gpa_source_url='https://www.fitnyc.edu/documents/ire/cds-2025-26-updated3.pdf' where id=144;

-- Cooper Union: US News 공학 9위(학교 공개)·단과대별 합격률 추가 (2026-09-22)
update public.schools set intro_ko='건축·미술·공학 3개 단과대학으로 이루어진 뉴욕의 소규모 사립대로, 모든 학부생에게 반액 등록금 장학금을 준다. 앨버트 너켄 공과대학은 화학·토목·전기·기계공학(B.E.)과 컴퓨터과학·일반공학(B.S.) 과정을 운영하며 학부생의 절반 이상이 공학 전공이며, 학교가 공개한 US News 2026 기준 학부 공학 프로그램 9위다.', intro_en='A small private college in New York City made up of schools of architecture, art, and engineering, awarding every undergraduate a half-tuition scholarship. The Albert Nerken School of Engineering offers B.E. programs in chemical, civil, electrical and mechanical engineering plus B.S. programs in computer science and general engineering, and engineering students make up over half of the undergraduate body; the school cites a U.S. News 2026 ranking of #9 among undergraduate engineering programs.', what_they_value='미술대학 지원자는 포트폴리오·스케치북과 함께 학교가 출제하는 Hometest를 제출하며, 학교는 이를 통해 시각적 상상력, 콘셉트 전개, 손으로 만드는 능력, 지시를 따르고 시간을 관리하는 능력을 본다고 밝힌다. 건축대학은 Studio Test를 입학 심사의 핵심으로 두고 창의적 사고와 문제 해결 능력을 평가하며, 건축 경험은 요구하지 않는다. 공과대학은 미술·건축과 달리 SAT/ACT 제출이 필수이고 포트폴리오·Hometest는 없으며, 고교에서 미적분·화학·물리를 각 1년 이상 이수할 것과 STEM 교사 추천서 1통 이상을 요구한다. 학교가 공개한 2025년 가을 기준 단과대별 합격률(Common App 제출 기준)은 공학 16%, 미술 8%, 건축 4%다. 학부 입학 과정에서 인터뷰는 진행하지 않는다.', what_they_value_en='School of Art applicants submit a portfolio and sketchbook along with the school-issued Hometest, which the school says shows visual imagination, concept development, hands-on making, and how well applicants follow directions and manage time. The School of Architecture treats its Studio Test as a cornerstone of admissions, assessing creative thinking and problem-solving, and requires no prior architecture experience. The School of Engineering, unlike Art and Architecture, requires the SAT or ACT and has no portfolio or Hometest; it asks applicants to complete at least one year each of calculus, chemistry and physics in high school and to submit at least one recommendation from a STEM teacher. The school''s published fall 2025 acceptance rates by school (based on Common Applications submitted) are 16% for Engineering, 8% for Art and 4% for Architecture. No interviews are conducted in undergraduate admissions.' where id=141;

-- MICA·SCAD·MassArt 추가 + UCLA 예술대학 정보 (2026-09-23, 공식 출처)
insert into public.schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note, ed_offered, ed2_offered, ea_offered, rea_offered, ed_timing, ed2_timing, ea_timing, rd_timing, deadlines_source_url, deadlines_verified_at, c7_very_important, c7_source_url, intro_en, what_they_value_en, location_note_en, gpa_note_en, intl_aid_count, intl_aid_avg, intl_aid_year, meets_full_need_intl, merit_intl, meets_full_need_all, no_loan, merit_note, aid_source_url, kind, lac_rank, overall_accept_rate, ed_applied, ed_admitted, ed_cds_year, portfolio_req, portfolio_req_en, portfolio_source_url, art_programs) values
(145, 'Maryland Institute College of Art', '메릴랜드 인스티튜트 예술대학 (MICA)', null, null, null, null, null, null, null, null, '{}'::text[], 'MICA는 포트폴리오를 예술에 대한 진지한 헌신, 역량, 그리고 MICA의 엄격한 스튜디오 환경에서 성공할 가능성을 보여 주는 가장 의미 있는 지표라고 밝힌다. 입학사정위원회는 지원자가 아이디어와 개념을 시각적으로 표현하는 방식을 평가하고, 시각 예술 분야의 이전 교육과 기술적 역량도 함께 본다. 추천서는 선택 사항이지만 미술과 학업 경험을 말해 줄 수 있는 교사·카운슬러의 추천이 중요하다고 안내한다.', 'https://www.mica.edu/admissions/undergraduate-admission/', 'test-optional', 'MICA는 1826년에 설립되어 미국에서 가장 오래 학위를 계속 수여해 온 미술대학이며, 학부 BFA 전공과 대학원 과정을 운영한다.', '메릴랜드주 볼티모어에 있다.', false, false, true, false, null, null, '11월 중순', '2월 초', 'https://www.mica.edu/admissions/undergraduate-admission/', '2026-09-23', null, null, 'Founded in 1826, MICA is the oldest continuously degree-granting college of art in the United States and offers undergraduate BFA majors as well as graduate programs.', 'MICA states that the portfolio is the most meaningful indicator of serious artistic commitment, ability, and potential to succeed in its rigorous studio environment. The Admission Committee assesses how applicants express ideas and concepts visually, and also evaluates previous training in the visual arts and technical skill. Letters of recommendation are optional, but MICA says recommendations from teachers or counselors who can speak to your art and academic experiences are important.', 'Located in Baltimore, Maryland.', null, null, null, null, null, 'MICA merit/competitive scholarships', null, null, 'MICA''s merit-based competitive scholarships recognize artistic talent and academic achievement and are open to students from the United States and abroad; new applicants are considered through the admission application. International students may also submit the CSS Profile to be considered for need-based aid.', 'https://www.mica.edu/admissions/financial-aid/undergraduate-financial-aid/financing-options/scholarships/competitive-scholarships/', 'art', null, null, null, null, null, '포트폴리오는 필수이며 최근 작품 10~15점을 제출한다. 지정 과제(프롬프트)나 실기 홈테스트는 없다. 지원서(Common App 또는 MICA 자체 지원서)를 제출한 뒤 안내에 따라 MICA 지원자 포털(Applicant Portal)에 업로드하며, 이미지·영상·사운드 파일을 올릴 수 있다.', 'A portfolio is required: 10-15 pieces of recent artwork. There are no prompts and no home exam. After submitting the application (Common App or MICA''s own application), applicants upload the portfolio through the MICA Applicant Portal; image, video, and sound files are accepted.', 'https://www.mica.edu/admissions/undergraduate-admission/portfolio-preparation/', array['arts','graphic_design','film','game_design','interior_design']::text[]),
(146, 'Savannah College of Art and Design', '사바나 예술 디자인 대학 (SCAD)', null, null, null, null, '입학 1학년 평균 고교 GPA 3.64 (2025년 가을학기, SCAD Fact Book)', null, null, null, '{}'::text[], 'SCAD는 고교 성적을 기본으로 보며, GPA 3.0 미만이거나 SAT 1080(수학+읽기)·ACT 21 미만인 지원자에게 포트폴리오·추천서·학업계획서(500단어 이내)·인터뷰 같은 보충 자료 제출을 강하게 권한다. 시험 점수는 선택 제출이며, 점수가 없어도 심사와 장학금 검토에 불이익이 없다고 밝힌다. 포트폴리오는 학부 입학 필수가 아니고 주로 성취 장학금 심사에 쓰인다.', 'https://www.scad.edu/sites/default/files/PDF/SCADFactBook-info.pdf?121924', 'test-optional', 'SCAD는 1978년에 세워진 사립 비영리 예술·디자인 대학으로, 조지아주 사바나·애틀랜타 캠퍼스와 프랑스 라코스트 캠퍼스, 온라인 과정(SCADnow)을 운영한다.', '조지아주 사바나에 있다 (애틀랜타 캠퍼스와 프랑스 라코스트 캠퍼스도 있다).', false, false, false, false, null, null, null, null, 'https://www.scad.edu/admission/admission-information/first-year', '2026-09-23', null, null, 'SCAD is a private nonprofit art and design university founded in 1978, with campuses in Savannah and Atlanta, Georgia, a location in Lacoste, France, and online programs through SCADnow.', 'SCAD reviews high school academic records and strongly encourages applicants with a GPA below 3.0 or scores below 1080 SAT (math and reading) / 21 ACT to submit supplementary materials such as a portfolio, recommendations, a statement of purpose (up to 500 words), or an interview. Testing is optional, and SCAD states that not submitting scores does not affect admission or scholarship review. A portfolio is not required for undergraduate admission and is used mainly for achievement scholarship consideration.', 'Located in Savannah, Georgia (with additional locations in Atlanta, Georgia and Lacoste, France).', 'Average high school GPA of incoming first-year students: 3.64 (fall 2025, SCAD Fact Book)', null, null, null, null, 'International Student Scholarship', null, false, 'Incoming undergraduates, including international students, are automatically reviewed for GPA-based academic scholarships after admission, and those who submit a résumé/list of achievements and/or portfolio are also reviewed for achievement scholarships. The International Student Scholarship requires meeting or exceeding admission requirements and a 500-word essay.', 'https://www.scad.edu/admission/financial-aid-and-scholarships/scholarships', 'art', null, 74.9, null, null, null, '학부(1학년·편입) 입학에는 포트폴리오나 오디션이 필수가 아니다. 다만 성취 장학금(achievement honors scholarship) 심사를 받으려면 활동 이력서(résumé/list of achievements)와 함께 포트폴리오를 내도록 강하게 권하며, 포트폴리오 제출이 입학 결정에 불리하게 작용하지 않는다고 밝힌다. 제출은 SlideRoom(건당 US$10)으로 하고, 시각예술·패션 부문은 10~20점, 영상 등 시간 기반 미디어는 3~5분, 글쓰기는 5~15쪽 분량이며 비즈니스·마케팅·연기(현장 오디션 대체 가능)·승마·STEM 부문도 있다. 포트폴리오가 지망 전공과 일치할 필요는 없다.', 'A portfolio or audition is not required for undergraduate (first-year or transfer) admission. Applicants are strongly encouraged to submit a portfolio along with a résumé/list of achievements to be considered for achievement honors scholarships, and SCAD states that submitting one does not adversely affect the admission decision. Portfolios are submitted via SlideRoom (US$10 fee); visual arts/fashion calls for 10-20 pieces, time-based media 3-5 minutes, writing 5-15 pages, with additional categories for business/marketing, acting (in-person audition accepted), equestrian, and STEM. The portfolio need not match the intended major.', 'https://www.scad.edu/admission/portfolio-and-writing-guidelines/undergraduate-portfolios', array['arts','graphic_design','fashion_design','film','game_design','industrial_design','interior_design']::text[]),
(147, 'Massachusetts College of Art and Design', '매사추세츠 예술디자인대학 (MassArt)', null, null, null, null, null, null, null, null, '{}'::text[], 'MassArt는 학업 준비도, 창작 잠재력, 개인적 성취를 종합적으로(holistic) 검토하며, 포트폴리오·에세이·추천서·활동 목록이 모두 평가 요소라고 밝힌다. 포트폴리오에서는 기술과 완성도(Craft and Technique), 탐구(Exploration), 콘셉트와 관점, 문제 해결, 맥락을 본다. 권장 GPA는 3.0이며 3.0 미만 지원자도 검토하지만 2.3 미만은 입학시키지 않는다고 안내한다.', 'https://massart.edu/admissions/first-time-undergraduates/admissions-standards/', 'test-free', 'MassArt는 매사추세츠 주립 공립 예술디자인대학으로, 1학년 Studio Foundation 과정 후 BFA 전공을 선택한다.', '매사추세츠주 보스턴에 있다.', false, false, true, false, null, null, '12월 초', '2월 중순', 'https://massart.edu/admissions/first-time-undergraduates/how-to-apply/', '2026-09-23', null, null, 'MassArt is a public art and design college in the Massachusetts state system, where students complete a first-year Studio Foundation program before entering a BFA major.', 'MassArt reviews applications holistically, considering academic preparation, creative potential, and personal accomplishments, and states that the portfolio, essay, letter of recommendation, and activity list are all factors. In the portfolio it looks for craft and technique, exploration, concept and point of view, problem solving, and context. The recommended GPA is 3.0; applicants below 3.0 are considered, but students are not admitted with a high school GPA below 2.3.', 'Located in Boston, Massachusetts.', null, null, null, null, null, 'MassArt Provost''s Scholarship', null, null, 'International undergraduates may be considered for merit-based scholarships through the admission application but are not eligible for federal aid; MassArt Provost''s Scholarships are merit-based awards for accepted first-year and transfer applicants from outside New England, renewable for up to four years. Test scores are not used for merit scholarship consideration.', 'https://massart.edu/costs-aid/for-undergraduates/types-of-aid/', 'art', null, null, null, null, null, '포트폴리오는 필수이며 최근 2년 이내 작품 12~15점을 제출한다(12점 미만은 불가). 지정 과제나 홈테스트는 없고 참고용 샘플 프롬프트만 제공된다. Common App 제출 후 받는 MassArt 지원자 포털(Applicant Portal)에 업로드하며, 음악·공연·문예 창작물은 검토하지 않고 AI를 활용한 작품은 사용 방식을 설명해야 한다.', 'A portfolio is required: 12-15 pieces completed within the past two years (fewer than 12 is not accepted). There is no required assignment or home test; only optional sample prompts are provided. It is uploaded through the MassArt Applicant Portal after submitting the Common App; music, theater, and creative writing are not reviewed, and any AI-supported work must include a description of how AI was used.', 'https://massart.edu/admissions/first-time-undergraduates/preparing-your-portfolio/', array['arts','graphic_design','fashion_design','film','industrial_design']::text[])
on conflict (id) do nothing;
update public.schools set art_programs=array['arts','graphic_design','game_design','film','music']::text[], portfolio_req='예술 계열 전공은 UC 지원서(11월 말 마감)에서 해당 전공을 1지망으로 선택해야 하고, 별도의 보충 지원서(supplemental application)를 따로 내야 한다. 예술·건축대학(Arts and Architecture) 전공은 SlideRoom으로 포트폴리오를 내며, Design·Games·Computational Art·Dance·World Arts and Cultures는 12월 중순, Art는 1월 하순이 마감이다(Art는 작품 이미지 8~10장과 글). 영화·TV(Film and Television)는 Acceptd로 12월 초까지 에세이 2편, 글쓰기 샘플, 3분 이내 영상 인터뷰, 추천서 2부를 낸다. 음악대학(Herb Alpert School of Music)은 Acceptd로 12월 초까지 보충 지원서를 내고, 1차 심사를 통과하면 1월 말에 오디션·인터뷰를 본다. 2025년 가을 1학년 기준 공식 합격률은 예술·건축대학 5.1%(Art 3.3%, Design | Media Arts 3.1%), 영화·TV 1.3%, 음악대학 24%다. 건축(Architectural Studies)은 1학년 입학을 받지 않고 2학년 때 전과로 들어간다.', portfolio_req_en='Arts applicants must list the arts major as their first choice on the UC Application (due late November) and also submit a separate supplemental application. Arts and Architecture majors submit portfolios through SlideRoom: Design, Games, Computational Art, Dance, and World Arts and Cultures are due in mid-December, and Art is due in late January (8-10 images of original work plus written statements). Film and Television uses Acceptd and is due in early December. It requires two essays, a writing sample, a video interview of up to 3 minutes, and two letters of recommendation. Music majors submit through Acceptd in early December, and applicants who pass prescreening are invited to late-January auditions or interviews. UCLA''s published fall 2025 first-year admit rates are 5.1% for the School of the Arts and Architecture (Art 3.3%, Design | Media Arts 3.1%), 1.3% for Film and Television, and 24% for the Herb Alpert School of Music. Architectural Studies does not admit first-years; students transfer in during sophomore year.', portfolio_source_url='https://admission.ucla.edu/apply/supplemental-applications' where id=18;
update public.schools set avg_gpa=3.64, avg_gpa_scale='4.0 scale', avg_gpa_year='SCAD Fact Book fall 2025', avg_gpa_source_url='https://www.scad.edu/sites/default/files/PDF/SCADFactBook-info.pdf?121924' where id=146;

